//! Pinyin initials of Chinese characters, so that the fuzzy matcher
//! (`fuzzy.zig`) finds Chinese text by the first letters of its readings
//! (`xjbq` finds 新建标签). A character's initials are the first letters
//! of its modern readings, all of them for characters with several
//! (乐 has `l` and `y`).
//!
//! Covers the CJK Unified Ideographs block U+4E00..U+9FFF; the table in
//! `pinyin/initials.zig` is generated by `scripts/gx_pinyin.py` from
//! pinyin-data (MIT) and the Unicode Unihan data it builds on (Unicode
//! License V3), whose license texts are next to the table. Only depends
//! on `std`.
const std = @import("std");
const table = @import("pinyin/initials.zig");

/// A set of letters: bit `c - 'a'` for letter `c`.
pub const Initials = u32;

const last: u21 = table.first + table.primary.len - 1;

comptime {
    std.debug.assert(table.primary.len == 0x9FFF - table.first + 1);
}

const Extra = struct { cp: u16, initials: Initials };

/// `table.extra` with the letters as sets.
const extras: [table.extra.len]Extra = extras: {
    @setEvalBranchQuota(20_000);
    var result: [table.extra.len]Extra = undefined;
    for (table.extra, &result, 0..) |entry, *out, i| {
        if (i > 0 and entry[0] <= table.extra[i - 1][0]) @compileError("pinyin extras are not ascending");
        var set: Initials = 0;
        for (entry[1]) |letter| set |= bit(letter);
        out.* = .{ .cp = entry[0], .initials = set };
    }
    break :extras result;
};

fn bit(letter: u8) Initials {
    return @as(Initials, 1) << @intCast(letter - 'a');
}

/// The initials of `cp`; empty for anything but a CJK unified ideograph
/// with a known reading.
pub fn initials(cp: u21) Initials {
    if (cp < table.first or cp > last) return 0;
    const primary = table.primary[cp - table.first];
    if (primary == '.') return 0;
    var set = bit(primary);
    const key: u16 = @intCast(cp);
    var lo: usize = 0;
    var hi: usize = extras.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (extras[mid].cp < key) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo < extras.len and extras[lo].cp == key) set |= extras[lo].initials;
    return set;
}

/// Whether `set` holds the ASCII letter `letter` (`a`..`z`; anything else
/// is never held).
pub fn has(set: Initials, letter: u21) bool {
    if (letter < 'a' or letter > 'z') return false;
    return set & bit(@intCast(letter)) != 0;
}

fn expectInitials(cp: u21, expected: []const u8) !void {
    var set: Initials = 0;
    for (expected) |letter| set |= bit(letter);
    try std.testing.expectEqual(set, initials(cp));
}

test "initials of common characters" {
    try expectInitials('新', "x");
    try expectInitials('建', "j");
    try expectInitials('标', "b");
    try expectInitials('签', "q");
    try expectInitials('页', "y");
    try expectInitials('设', "s");
    try expectInitials('置', "z");
    try expectInitials('一', "y");
}

test "polyphones have every modern initial, not archaic ones" {
    try expectInitials('乐', "ly");
    try expectInitials('行', "hx");
    try expectInitials('长', "cz");
    try expectInitials('单', "cds");
    // 重 has an archaic reading tóng that is left out.
    try expectInitials('重', "cz");
    try expectInitials('的', "d");
}

test "anything but a known CJK unified ideograph has none" {
    for ([_]u21{ 'a', 'Z', '1', ' ', 0x3000, 0xFF41, 0x3400, 0x4DFF, 0xA000, 0x20000, 0x10FFFF }) |cp| {
        try std.testing.expectEqual(@as(Initials, 0), initials(cp));
    }
    // The ends of the block are looked up without overrunning the table.
    try std.testing.expect(initials(table.first) != 0);
    _ = initials(last);
}

test "has" {
    const set = initials('乐');
    try std.testing.expect(has(set, 'l'));
    try std.testing.expect(has(set, 'y'));
    try std.testing.expect(!has(set, 'x'));
    try std.testing.expect(!has(set, 'L'));
    try std.testing.expect(!has(set, '新'));
    try std.testing.expect(!has(0, 'a'));
}
